  GameObject oddsDialog;GameRuntime game;Transform content;Text header,notice;Button draw,video,voucher;string page="permanent",signature="",transaction="";CancellationTokenSource cancellation;readonly IRewardedVideoProvider provider=new UnavailableRewardedVideoProvider();readonly List<Action> refresh=new List<Action>();
  public void Initialize(GameRuntime runtime,bool embedded=false){game=runtime;StorefrontUI.FitWidth(transform);ItemPortrait.Sprites=game.WorkshopPrefab.ItemSprites;header=WorkshopUIFactory.Label("GemHeader",transform,"",16,72);header.gameObject.SetActive(!embedded);var nav=PresentationLayout.Grid("GemNavigation",transform,2,ProgressionVisibility.Gumball(game.State)?4:3,44);nav.gameObject.SetActive(!embedded);foreach(string section in new[]{"permanent","time","materials","capsule"}){string id=section;if(id=="capsule"&&!ProgressionVisibility.Gumball(game.State))continue;var tab=WorkshopUIFactory.Button("GemPage-"+id,nav,id=="permanent"?"Upgrades":id=="time"?"Zeit":id=="materials"?"Material":"Gumball",()=>{page=id;Build();Canvas.ForceUpdateCanvases();game.Content.GetComponentInParent<ScrollRect>().verticalNormalizedPosition=1;});GameTheme.CompactAction(tab,false);}notice=WorkshopUIFactory.Label("GemNotice",transform,"",14,24);AdaptiveTextHeight.Attach(notice);content=WorkshopUIFactory.Vertical("GemContent",transform).transform;StorefrontUI.FitWidth(content);Build();}
  public void OpenPage(string selected){if(selected=="capsule"&&!ProgressionVisibility.Gumball(game.State))selected="permanent";if(page==selected)return;page=selected;Build();}string Signature()=>page+":"+game.State.Upgrades.processed.Length+":"+game.State.Capsules.draws+":"+game.State.Capsules.hasRequest+":"+VoucherRules.Available(game.State);
