  ActionCard Card(string name,string title){var c=Instantiate(game.CardPrefab,content);c.name=name;c.Title.text=title;c.Title.fontSize=16;c.Detail.fontSize=14;c.Icon.gameObject.SetActive(false);c.gameObject.AddComponent<CompactActionCard>();return c;}
