  void Build(){signature=Signature();WorkshopUIFactory.Clear(content);refresh.Clear();draw=video=voucher=null;var s=game.State;if(page=="capsule"&&!ProgressionVisibility.Gumball(s))page="permanent";
   if(page!="capsule"){foreach(var offer in GemBalance.Offers.Where(o=>o.Section==page)){string id=offer.Id;int expected=s.Upgrades.processed.Length;var card=Card("GemOffer-"+id,offer.Name);var price=StorefrontUI.Product(card);card.Icon.gameObject.SetActive(true);card.Icon.sprite=game.Users.transform.parent.Find("ResourceIcon").GetComponent<Image>().sprite;card.Icon.preserveAspect=true;card.Button.onClick.AddListener(()=>{game.GetComponent<RewardPresentation>()?.SetOrigin(card.transform);bool ok=game.Act(v=>v.Upgrades.processed.Length==expected?GemShop.Buy(v,id):v,"gem-offer");notice.text=ok?"Kauf und Wirkung gespeichert.":"Kein weiterer Kauf. Angebot und Bestand prüfen.";});refresh.Add(()=>{var q=GemShop.Quote(game.State,id);StorefrontUI.Price(price,StorefrontUI.Gem(game),q.Cost.ToString(),q.Enabled?GameTheme.Enough:GameTheme.Missing);card.Detail.text=offer.Effect+(q.Reason==null?"":"\n"+UiLocalizedText.Translate(Reason(q.Reason),game.State.Settings.language))+(q.HasTime?"\nRest "+Math.Ceiling(q.Remaining)+" s · Verkürzung "+Math.Ceiling(q.Applied)+" s":"");card.Button.interactable=game.Writable&&q.Enabled;});}return;}
   var art=Resources.Load<PresentationArt>("PixelUI/PresentationArt");var machine=WorkshopUIFactory.Node("CapsuleMachineArt",content,typeof(Image));WorkshopUIFactory.Size(machine,170);machine.GetComponent<Image>().sprite=art.Machine;machine.GetComponent<Image>().preserveAspect=true;machine.GetComponent<Image>().raycastTarget=false;
   var actionRow=WorkshopUIFactory.Horizontal("CapsuleActions",content,44);long next=Capsules.Quote(s).Next;draw=WorkshopUIFactory.Button("CapsuleDraw",actionRow.transform,"Ziehen",()=>{bool ok=game.Act(v=>Capsules.Draw(v,next),"capsule-gem");notice.text=ok?"Ergebnis gespeichert.":"Keine weitere Ziehung. Bestand und Freischaltung prüfen.";});GameTheme.ButtonStyle(draw,true);StorefrontUI.CurrencyButton(draw,StorefrontUI.Gem(game));video=WorkshopUIFactory.Button("CapsuleVideo",content,"Video nicht verfügbar",RequestVideo);
   voucher=WorkshopUIFactory.Button("CapsuleVoucher",content,"Gutschein einlösen",()=>{bool ok=game.Act(v=>Capsules.DrawVoucher(v,next),"capsule-voucher");notice.text=ok?"Gutschein eingelöst. Ergebnis gespeichert.":"Kein Gutschein verfügbar oder Gumball gesperrt.";});
   var ticketIcon=new GameObject("GumballVoucherIcon",typeof(RectTransform),typeof(Image));ticketIcon.transform.SetParent(voucher.transform,false);var ticketRect=(RectTransform)ticketIcon.transform;ticketRect.anchorMin=new Vector2(0,.5f);ticketRect.anchorMax=new Vector2(0,.5f);ticketRect.pivot=new Vector2(0,.5f);ticketRect.sizeDelta=new Vector2(38,30);ticketRect.anchoredPosition=new Vector2(7,0);var ticketImage=ticketIcon.GetComponent<Image>();ticketImage.sprite=VoucherSprite.Get();ticketImage.preserveAspect=true;ticketImage.raycastTarget=false;
   if(s.Capsules.hasRequest){string tx=s.Capsules.request.id;WorkshopUIFactory.Button("CapsuleCancel",content,"Offenen Videoauftrag abbrechen",()=>game.Act(v=>Capsules.CancelVideo(v,tx)));}
   var info=WorkshopUIFactory.Button("CapsuleInfo",actionRow.transform,"i",()=>{if(oddsDialog!=null)Destroy(oddsDialog);oddsDialog=StorefrontUI.Info(game,"CapsuleInformation","Gumball","");var body=oddsDialog.transform.Find("DetailPanel").GetComponentInChildren<ScrollRect>().content.Find("InfoBody");
   WorkshopUIFactory.Label("CapsuleOdds",body,"Item "+(GemBalance.ItemChance*100)+" % · Komponenten "+(GemBalance.ComponentChance*100)+" %\nCredits "+(GemBalance.CreditChance*100)+" % · Daten "+(GemBalance.DataChance*100)+" %\nGems "+(GemBalance.GemChance*100)+" % · Jackpot "+(GemBalance.JackpotChance*100)+" %\nItems: gewöhnlich, aus dem zugänglichen Pool.\nCredits/Daten: "+GemBalance.CreditSeconds[0]+"–"+GemBalance.CreditSeconds[1]+" Produktionssekunden (mind. "+GemBalance.CreditFloor+" / "+GemBalance.DataFloor+").\nGems: "+GemBalance.GemRange[0]+"–"+GemBalance.GemRange[1]+" · Jackpot: "+(GemBalance.CapsuleCost*GemBalance.JackpotMultiplier)+" Gems",14,200);
   var pool=SeasonRules.Pool(s);WorkshopUIFactory.Label("CapsulePerItemOdds",body,(s.Settings.language=="de"?"Je zugänglichem Itemtyp: ":"Each accessible item type: ")+(pool.Length==0?0:GemBalance.ItemChance*100/pool.Length).ToString("0.####")+" % · "+(s.Settings.language=="de"?"Gewöhnlich. Keine Auszahlung, kein Geldwert.":"Common. No cash-out or monetary value."),13,54);
   var itemOdds=WorkshopUIFactory.Vertical("CapsuleItemOdds",body);foreach(var type in pool)WorkshopUIFactory.Label("Odds-"+type,itemOdds.transform,SettingsRules.Text(s.Settings.language,"item:"+type),13,32);itemOdds.SetActive(false);WorkshopUIFactory.Button("ShowCapsuleItemOdds",body,s.Settings.language=="de"?"Itempool / Einzelchancen":"Item pool / individual odds",()=>itemOdds.SetActive(!itemOdds.activeSelf));
   foreach(var label in body.GetComponentsInChildren<Text>(true))AdaptiveTextHeight.Attach(label);
   });var infoSize=info.GetComponent<LayoutElement>();infoSize.minWidth=infoSize.preferredWidth=44;infoSize.flexibleWidth=0;GameTheme.CompactAction(info,false);
   if(!s.Capsules.hasLast)return;var r=s.Capsules.last;var receipt=Card("CapsuleReceipt","Ergebnis #"+r.id+" · "+r.payment);receipt.transform.SetSiblingIndex(0);receipt.GetComponent<LayoutElement>().preferredHeight=120;receipt.Button.interactable=false;receipt.Detail.text=r.kind=="item"?ItemBalance.Items[Workshop.Index(r.itemType)].Name+"\n"+ItemBalance.Rarities[r.rarity]:r.kind=="components"?string.Join("\n",r.components.Select((n,i)=>n>0?ItemBalance.ComponentNames[i]+" × "+n:"").Where(t=>t!="")):r.resourceId+" + "+ScientificNumber.FromData(r.amount).ToString();
   if(r.kind=="item"){receipt.Icon.gameObject.SetActive(true);receipt.Icon.color=Color.clear;var p=Instantiate(game.WorkshopPrefab.PortraitPrefab,receipt.Icon.transform);var rect=(RectTransform)p.transform;rect.anchorMin=rect.anchorMax=new Vector2(.5f,.5f);rect.sizeDelta=new Vector2(58,58);rect.anchoredPosition=Vector2.zero;p.Bind(new ItemInstance{type=r.itemType,rarity=r.rarity});p.Caption.text="";p.Button.interactable=false;p.Button.targetGraphic.raycastTarget=false;}else if(r.kind=="components"){receipt.Icon.gameObject.SetActive(true);receipt.Icon.sprite=game.WorkshopPrefab.ComponentSprites[Array.FindIndex(r.components,n=>n>0)];receipt.Icon.preserveAspect=true;}
  }
  async void RequestVideo(){if(transaction!=""||!Capsules.Quote(game.State).VideoAllowed)return;if(!game.AcquireRewardRequest())return;string tx="capsule-video-"+Guid.NewGuid().ToString("N");if(!game.Act(s=>Capsules.BeginVideo(s,tx)))return;if(PurchaseRules.AdFree(game.State)){game.Act(s=>Capsules.ClaimAdFree(s,tx),"capsule-video");notice.text="Werbefrei-Anspruch gespeichert. Keine Anzeige abgespielt.";return;}transaction=tx;cancellation=new CancellationTokenSource();RewardProviderResult result;try{result=await provider.ShowAsync("capsule",tx,cancellation.Token);}catch(OperationCanceledException){result=RewardProviderResult.Cancelled;}catch{result=RewardProviderResult.Failed;}if(game!=null)game.Act(s=>Capsules.CompleteRequestedVideo(s,tx,result.ToString().ToLowerInvariant()),"capsule-video");if(this!=null){transaction="";notice.text=result==RewardProviderResult.Unavailable?"Keine Werbequelle. Keine Belohnung und kein Limit verbucht.":"Videoauftrag beendet.";cancellation?.Dispose();cancellation=null;}}
  void OnDisable(){if(oddsDialog!=null){Destroy(oddsDialog);oddsDialog=null;}cancellation?.Cancel();if(game!=null&&transaction!="")game.Act(s=>Capsules.CancelVideo(s,transaction));}
 }
